const a="Debido a que cambió su calendario de pago, tendrá que ejecutar algunas nóminas de transición. Las nóminas de transición le permiten pagar a los empleados por cualquier día laborado durante los intervalos entre calendarios de pago. Puede optar por omitirlas, pero es su responsabilidad asegurarse de que los empleados reciban su pago correctamente. La funcionalidad de nómina regular se bloquea hasta que ejecute u omita las nóminas de transición.",e="Nómina de transición - {{dateRange}}",i="Ejecutar nómina de transición",n={body:"Omitir esta nómina significa que los empleados no recibirán pago por el período de transición. Es su responsabilidad asegurarse de que los empleados reciban su pago correctamente.",confirmCta:"Omitir nómina",title:"¿Omitir la nómina de transición de {{dateRange}}?"},s="Omitir esta nómina",r="Se omitió la nómina de transición",o={alertDescription:a,alertTitle:e,runPayroll:i,skipDialog:n,skipPayroll:s,skipSuccessAlert:r};export{a as alertDescription,e as alertTitle,o as default,i as runPayroll,n as skipDialog,s as skipPayroll,r as skipSuccessAlert};
